"""Self-contained interactive report from descriptive, scope-separated audit data."""
import json
from pathlib import Path

HERE=Path(__file__).resolve().parent
result=json.loads((HERE/'results.json').read_text())
# Do not inline huge source receipts, just the reduced chart rows and statistics.
data={'cells':result['cells'],'baselines':{name:{'process_means_ms':x.get('process_means_ms'),'runs':[{k:r[k] for k in ('name','arms')} for r in x['runs']]} for name,x in result['baselines'].items()},'mechanisms':{'G01': 'Dead persistence copies', 'G02': 'Dead mip chains', 'G03': 'Early alpha rejection', 'G04': 'Translucent fast path', 'G05': 'Reflection refinement', 'G06': 'Ambient occlusion', 'G07': 'Depth sample reuse', 'G08': 'Spatial lighting reuse', 'G09': 'Parallax height reuse', 'G10': 'Bloom query reuse', 'C01': 'Occlusion admission', 'C02': 'Bloom shading rate', 'N01': 'Native CPU command/cache work', 'N02': 'Attachment lifetime', 'N03': 'History/copy lifetime', 'N04': 'Overwritten or zero-work shading'},'controls':result['control_cohorts'],'runs':[{k:r.get(k) for k in ('name','shader','goal','kind','phase','case','validity','restored','plot_arms','frame_time_reduction_pct','comparison_order','error','work_qualification')} for r in result['runs'] if r['kind'] in ('test','control')]}
for cell in data['cells']:
    cell.pop('runs',None);route=cell.pop('route',{});cell['implementation']=route.get('feature') or route.get('candidate') or ('native CPU bundle' if route.get('features') else '')
# Only fields actually used by the inline chart; complete provenance stays in results.json.
cell_keys=('shader','goal','status','scope_note','arms','effects_pct','plotted_case','plotted_phase','plotted_runs','implementation','preferred_case_note')
data['cells']=[{k:c[k] for k in cell_keys if k in c} for c in data['cells']]
data['controls']={shader:{case:{'effects_pct':c['effects_pct']} for case,c in cohorts.items()} for shader,cohorts in data['controls'].items()}
metric_keys=('mean_total_frame_ms','sd_total_frame_ms','variance_total_frame_ms2')
for run in data['runs']:
    run.pop('error',None)
    if run.get('plot_arms'):run['plot_arms']={arm:{k:m[k] for k in metric_keys} for arm,m in run['plot_arms'].items()}
for baseline in data['baselines'].values():
    for run in baseline['runs']:run['arms']={arm:{k:m[k] for k in metric_keys} for arm,m in run['arms'].items()}
encoded=json.dumps(data,separators=(',',':')).replace('<',chr(92)+'u003c')
page='''<!doctype html><html><head><meta charset="utf-8"><style>
:root{font-family:var(--font-sans)}body{margin:0;color:var(--foreground)}p{line-height:1.45;margin:8px 0 12px}.muted{color:var(--muted-foreground,var(--muted))}.controls{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}button,select{font:inherit;padding:6px 9px;border:1px solid var(--border);border-radius:6px;color:var(--foreground);background:var(--secondary)}button[aria-pressed=true]{background:var(--primary);color:var(--primary-foreground)}.baseline{display:grid;grid-template-columns:1fr 1fr;gap:10px}.base{border:1px solid var(--border);border-radius:var(--radius);padding:16px;min-width:0}.base svg{display:block;width:100%;height:150px}.base p{font-size:12px;margin:4px 0}.chart{display:block;width:100%;min-width:690px;height:670px}.attempts{display:block;width:100%;min-width:690px;height:570px}.legend{font-size:12px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin:0 4px 0 10px}.native{background:var(--chart-2)}.candidate{background:var(--chart-1)}.returned{background:var(--chart-3)}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;border-bottom:1px solid var(--border);padding:6px 3px;vertical-align:top}details{margin:10px 0}summary{cursor:pointer}.scroll{overflow:auto}h3{font-size:15px;font-weight:600;margin:16px 0 5px}svg text{fill:var(--foreground);font-family:var(--font-sans);font-size:12px}svg .grid{stroke:var(--border)}svg .muted{fill:var(--muted-foreground,var(--muted))}.cell-title{font-size:13px}.note{font-size:12px}@media(max-width:480px){.baseline{grid-template-columns:1fr}.chart{height:700px}button,select{font-size:12px}}
</style></head><body>
<p>Native 3840 × 2160, native AA. Lower frame time is faster. These are native Windows RTX 5080 measurements. The campaign is in progress; missing cells remain untested. Failed/unrepaired startup cohorts stay separate. Primary baseline cards use gallery pose0, the minimal stack and native context and omit ShaderLOD; other stack/context baselines remain separate in results.json. Matched A controls below use the original pack with ShaderLOD installed and Off; C02 uses On with empty public requests and VRS Off.</p>
<p id="findings" class="note"></p>
<div class="baseline" id="baselines"></div>
<div class="controls" id="targets"></div>
<div class="controls"><label>Variability: <select id="uncertainty"><option value="within">Within-window frame SD</option><option value="between">Between-process mean SD</option></select></label></div>
<p class="legend"><span class="dot native"></span>Matched native A0 <span class="dot candidate"></span>Candidate <span class="dot returned"></span>Matched native A1<br>Dots: mean frame time, ms. Bars: ± sample standard deviation (SD), never confidence intervals. Exact variances are below, in ms².</p>
<div class="scroll"><svg id="chart" class="chart" viewBox="0 0 710 670" role="img" aria-label="All sixteen candidate goals and matched native frame times"></svg></div>
<p id="noise" class="note"></p><p class="note muted">Rows can use different scenes, settings and implementations. Discovery and confirmation remain separate; the plotted phase is labeled. Missing or refused cases have no invented timing bar. A requested feature or lower mean alone does not prove useful optimized work.</p>
<details><summary>Every valid timing, including alternate cases and discovery runs</summary><label>Candidate: <select id="attemptGoal"></select></label><div class="scroll"><svg id="attempts" class="attempts" viewBox="0 0 710 570" role="img" aria-label="Individual timing attempts and their frame standard deviations"></svg></div><p class="note muted">Each row is one process and one case. ABBA/BAAB B is the mean of two candidate windows; its bar is the average within-window frame SD. Different profiles/scenes are never pooled. Invalid attempts are retained in the linked evidence and excluded from timing bars.</p></details>
<details><summary>Exact variances and dispositions for all 64 cells</summary><div class="scroll" id="table"></div></details>
<script>const DATA=__DATA__;
const titles={makeup:'MakeUp Ultra Fast',bsl:'BSL',reimagined:'Complementary Reimagined',unbound:'Complementary Unbound'};
const goals=['G01','G02','G03','G04','G05','G06','G07','G08','G09','G10','C01','C02','N01','N02','N03','N04'];
const labels={HELD_LIFETIME_PROOF:'held: history/bank proof',NO_PROVEN_DEAD_LIFETIME:'no dead lifetime proved',NO_NATIVE_POM:'native has no POM',HELD_SMALL_OPPORTUNITY:'held: small opportunity',HELD_SHARED_GEOMETRY_PROOF:'held: geometry proof',NO_MAINTAINED_GENERAL_ROUTE:'no maintained general route',NO_DEAD_MIP_CHAIN_CURRENT:'native mip chains are live',CONSOLIDATED_WITH_G01:'shared G01 result; no additive gain',HARDWARE_UNSUPPORTED:'hardware unsupported',UNSUPPORTED_HARDWARE:'hardware unsupported',INVALID_OR_REFUSED:'invalid / refused; see evidence',UNTESTED_RTX5080:'pending RTX5080 test',PLANNED:'pending test',RUNNING:'running'};
let selected='makeup';const ns='http://www.w3.org/2000/svg';
document.querySelector('#findings').textContent=DATA.cells.filter(c=>c.arms).length+' of 64 target/goal cells currently have scored timing. Single-process results are preliminary; known-null controls, independent repeats and quality checks remain necessary. Functional checks supply no performance bars.';
function node(tag,attrs={},text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
function fmt(v,n=3){return typeof v==='number'?(v!==0&&Math.abs(v)<Math.pow(10,-n)?v.toExponential(2):v.toFixed(n)):'N/A'}
function esc(v){const e=document.createElement('span');e.textContent=String(v);return e.innerHTML}
function error(svg,x,y,half,color,r=3){svg.append(node('line',{x1:x-half,x2:x+half,y1:y,y2:y,stroke:color,'stroke-width':1.8}));if(half>0)for(const a of[x-half,x+half])svg.append(node('line',{x1:a,x2:a,y1:y-3,y2:y+3,stroke:color}));svg.append(node('circle',{cx:x,cy:y,r,fill:color}))}
for(const [shader,title]of Object.entries(titles)){const button=document.createElement('button');button.textContent=title;button.onclick=()=>{selected=shader;draw()};button.dataset.shader=shader;document.querySelector('#targets').append(button)}
function draw(){document.querySelectorAll('button[data-shader]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.shader===selected));const between=document.querySelector('#uncertainty').value==='between';const svg=document.querySelector('#chart');svg.replaceChildren();const cells=DATA.cells.filter(c=>c.shader===selected);const values=cells.flatMap(c=>c.arms?Object.values(c.arms).map(a=>a.window_means_ms.mean+(between?(a.window_means_ms.sd||0):a.mean_within_window_sd_ms)):[]);const maximum=Math.max(1,...values)*1.12;const left=56,right=700,width=right-left;const scale=v=>left+width*v/maximum;svg.append(node('text',{x:left,y:17,'class':'cell-title'},titles[selected]+' · total frame time (ms)'));
for(let i=0;i<=5;i++){const x=scale(maximum*i/5);svg.append(node('line',{x1:x,x2:x,y1:37,y2:641,'class':'grid'}));svg.append(node('text',{x,y:663,'text-anchor':'middle'},fmt(maximum*i/5,1)))}
goals.forEach((goal,i)=>{const cell=cells.find(c=>c.goal===goal),y=53+i*37;svg.append(node('text',{x:0,y:y+4},goal));if(!cell.arms){svg.append(node('text',{x:left+7,y:y+4,'class':'muted'},labels[cell.status]||cell.status.toLowerCase().replaceAll('_',' ')));return}for(const[arm,offset,color]of[['native',-8,'var(--chart-2)'],['candidate',0,'var(--chart-1)'],['return',8,'var(--chart-3)']]){const a=cell.arms[arm],sd=between?a.window_means_ms.sd:a.mean_within_window_sd_ms;error(svg,scale(a.window_means_ms.mean),y+offset,(sd||0)*width/maximum,color);const t=node('title',{},goal+' '+arm+': '+fmt(a.window_means_ms.mean)+' ms; within variance '+fmt(a.mean_within_window_variance_ms2)+' ms²; between process variance '+fmt(a.window_means_ms.variance)+' ms²');svg.lastChild.append(t)}const effect=cell.effects_pct;const text=(effect.mean>=0?'+':'')+fmt(effect.mean,1)+'% reduction · '+cell.plotted_phase+' n='+cell.plotted_runs+' · '+(cell.plotted_case||'primary')+' · '+cell.implementation.replaceAll('_',' ')+(between&&cell.plotted_runs<2?' · between SD N/A':'');svg.append(node('text',{x:left+5,y:y+23,'class':'muted',style:'font-size:10px'},text))});
const cohort=DATA.controls[selected]['original-null-primary'];document.querySelector('#noise').textContent=cohort?'Gallery pose 0 byte-identical control apparent reduction: '+fmt(cohort.effects_pct.mean,2)+'% mean, process SD '+fmt(cohort.effects_pct.sd,2)+' percentage points, n='+cohort.effects_pct.n+'. These differences are protocol/session noise, never optimization benefit.':'Current byte-identical control cohort is pending.';drawAttempts()}
for(const goal of goals){const o=document.createElement('option');o.value=goal;o.textContent=goal+' · '+DATA.mechanisms[goal];document.querySelector('#attemptGoal').append(o)}
function drawAttempts(){const svg=document.querySelector('#attempts');svg.replaceChildren();const goal=document.querySelector('#attemptGoal').value;const runs=DATA.runs.filter(r=>r.shader===selected&&r.goal===goal&&r.validity==='VALID'&&r.restored&&r.plot_arms);if(!runs.length){svg.append(node('text',{x:5,y:28},'No valid timing for this target/candidate. See disposition above.'));return}const max=Math.max(...runs.flatMap(r=>Object.values(r.plot_arms).map(m=>m.mean_total_frame_ms+m.sd_total_frame_ms)))*1.1;const left=100,width=590,scale=x=>left+x/max*width;for(let i=0;i<=5;i++){const x=scale(max*i/5);svg.append(node('line',{x1:x,x2:x,y1:28,y2:530,'class':'grid'}));svg.append(node('text',{x,y:553,'text-anchor':'middle'},fmt(max*i/5,1)))}const step=Math.min(65,490/runs.length);runs.forEach((r,i)=>{const y=45+i*step;svg.append(node('text',{x:0,y:y+3},'process '+(i+1)));for(const[arm,dy,color]of[['native',-8,'var(--chart-2)'],['candidate',0,'var(--chart-1)'],['return',8,'var(--chart-3)']]){const m=r.plot_arms[arm];error(svg,scale(m.mean_total_frame_ms),y+dy,m.sd_total_frame_ms/max*width,color);svg.lastChild.append(node('title',{},r.name+' / '+arm+': '+fmt(m.mean_total_frame_ms)+' ms; variance '+fmt(m.variance_total_frame_ms2)+' ms²'))}svg.append(node('text',{x:left,y:y+25,'class':'muted',style:'font-size:10px'},(r.case||'primary')+' · '+(r.phase||'discovery')+' · '+(r.comparison_order||'ABA')+' · '+fmt(r.frame_time_reduction_pct,2)+'% reduction · '+(r.work_qualification||'').replaceAll('_',' ').toLowerCase()))})}
document.querySelector('#attemptGoal').onchange=drawAttempts;
document.querySelector('#uncertainty').onchange=draw;
for(const [shader,title]of Object.entries(titles)){const b=DATA.baselines[shader],card=document.createElement('div');card.className='base';const heading=document.createElement('strong');heading.textContent=title+' native baseline';card.append(heading);const svg=node('svg',{viewBox:'0 0 310 150',role:'img'});const windows=b.runs.flatMap((r,ri)=>Object.entries(r.arms).map(([name,m])=>({run:ri+1,name,...m})));const ymax=Math.max(1,...windows.map(w=>w.mean_total_frame_ms+w.sd_total_frame_ms))*1.12;const ymin=0,step=260/Math.max(1,windows.length);for(let i=0;i<=3;i++){const y=120-95*i/3;svg.append(node('line',{x1:32,x2:305,y1:y,y2:y,'class':'grid'}));svg.append(node('text',{x:27,y:y+4,'text-anchor':'end'},fmt(ymax*i/3,1)))}windows.forEach((w,i)=>{const x=43+i*step,y=120-w.mean_total_frame_ms/ymax*95,half=w.sd_total_frame_ms/ymax*95;svg.append(node('line',{x1:x,x2:x,y1:y-half,y2:y+half,stroke:'var(--chart-1)','stroke-width':2}));const dot=node('circle',{cx:x,cy:y,r:3,fill:'var(--chart-1)'});dot.append(node('title',{},'Process '+w.run+' '+w.name+': '+fmt(w.mean_total_frame_ms)+' ms; sample variance '+fmt(w.variance_total_frame_ms2)+' ms²'));svg.append(dot);svg.append(node('text',{x,y:143,'text-anchor':'middle',style:'font-size:10px'},'r'+w.run+'/'+w.name.split('_').pop()))});card.append(svg);const p=document.createElement('p');const spread=b.process_means_ms;p.textContent=spread?'Mean '+fmt(spread.mean)+' ms · between-process variance '+fmt(spread.variance)+' ms² (n='+spread.n+').':'Pending.';card.append(p);const note=document.createElement('p');note.className='muted';note.textContent='Main mod absent. Each process: 120s conditioning, 3 × 20s windows. Bars: within-window frame SD.';card.append(note);document.querySelector('#baselines').append(card)}
let table='<table><thead><tr><th>Target / goal</th><th>Disposition / phase</th><th>Mean ms: A0 / B / A1</th><th>Within variance ms²: A0 / B / A1</th><th>Between-process variance ms²: A0 / B / A1</th></tr></thead><tbody>';
for(const shader of Object.keys(titles))for(const goal of goals){const c=DATA.cells.find(x=>x.shader===shader&&x.goal===goal);const values=key=>c.arms?['native','candidate','return'].map(a=>fmt(key(c.arms[a]))).join(' / '):'N/A';table+='<tr><td>'+esc(titles[shader]+' / '+goal+' · '+DATA.mechanisms[goal])+'</td><td>'+esc(c.status+(c.plotted_case?' / '+c.plotted_case:'')+(c.plotted_phase?' / '+c.plotted_phase+' n='+c.plotted_runs:''))+(c.implementation?'<br>'+esc(c.implementation):'')+(c.scope_note?'<br><span class=muted>'+esc(c.scope_note)+'</span>':'')+(c.preferred_case_note?'<br>'+esc(c.preferred_case_note):'')+'</td><td>'+values(a=>a.window_means_ms.mean)+'</td><td>'+values(a=>a.mean_within_window_variance_ms2)+'</td><td>'+values(a=>a.window_means_ms.variance)+'</td></tr>'}document.querySelector('#table').innerHTML=table+'</tbody></table>';draw();
</script></body></html>'''.replace('__DATA__',encoded)
(HERE/'interactive-charts.html').write_text(page)
print(json.dumps({'html':str(HERE/'interactive-charts.html'),'bytes':len(page.encode())}))
